def transform(grid):
    n, m = len(grid), len(grid[0])
    a, b = n // 2, m // 2
    quadrants = [
        (range(a), range(b), lambda i: (i, i)),
        (range(a), range(b + 1, m), lambda i: (i, m - 1 - i)),
        (range(a + 1, n), range(b), lambda i: (a + 1 + i, b - 1 - i)),
        (range(a + 1, n), range(b + 1, m), lambda i: (a + 1 + i, b + 1 + i)),
    ]
    best = None
    for rows, cols, path in quadrants:
        colors = {grid[r][c] for r in rows for c in cols if grid[r][c] != 7}
        for color in colors:
            hits = sum(0 <= r < n and 0 <= c < m and grid[r][c] == color
                       for r, c in (path(i) for i in range(a + 1)))
            candidate = (hits, color, path)
            if best is None or hits > best[0]:
                best = candidate
    _, color, path = best
    out = [[7] * m for _ in range(n)]
    for i in range(a + 1):
        r, c = path(i)
        out[r][c] = color
    return out
